    await usageRepo.incrementUsage(tenant.org.id, { seatsUsed: 1_000_000 });

    const check = await billingService.checkLimit(tenant.org.id, "seats", 500);

    expect(check.limit).toBe(Number.POSITIVE_INFINITY);
